import{_ as p,o as a,c as o,a5 as d}from"./chunks/framework.DJo0M80U.js";const n=JSON.parse('{"title":"MySQL 数据库迁移与重命名思路总结","description":"","frontmatter":{"title":"MySQL 数据库迁移与重命名思路总结","date":"2026-05-27T00:00:00.000Z","tags":["MySQL","数据库迁移","数据库重命名","表重命名"],"categories":["数据库"]},"headers":[],"relativePath":"posts/后端/MySQL/MySQL 数据库迁移与重命名思路总结.md","filePath":"posts/后端/MySQL/MySQL 数据库迁移与重命名思路总结.md","lastUpdated":1790163617000}'),c={name:"posts/后端/MySQL/MySQL 数据库迁移与重命名思路总结.md"};function l(t,e,i,r,_,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>这次问题的核心是把旧库 <code>liuwapocketmap</code> 迁移成新库 <code>liuwadi</code>。</p><p>同时需要把旧表前缀 <code>lwpm_</code> 改成新表前缀 <code>lwd_</code>。</p><p>迁移目标不是重新造一套空表再导数据。</p><p>迁移目标是保留原有数据、主键、索引、自增值和表关系。</p><h2 id="最重要的认知" tabindex="-1">最重要的认知 <a class="header-anchor" href="#最重要的认知" aria-label="Permalink to &quot;最重要的认知&quot;">​</a></h2><p>MySQL 不推荐直接重命名数据库。</p><p>正确方式是创建一个新的空数据库。</p><p>然后把旧库里的表整体移动到新库。</p><p>移动表时顺便修改表名。</p><p>这个动作应该使用 <code>RENAME TABLE</code> 完成。</p><p><code>CREATE DATABASE</code> 只会创建一个空库。</p><p>创建新库不会删除旧库数据。</p><p>只要不执行 <code>DROP DATABASE liuwapocketmap</code>，旧库数据就还在。</p><h2 id="为什么不能直接重新建表再导数据" tabindex="-1">为什么不能直接重新建表再导数据 <a class="header-anchor" href="#为什么不能直接重新建表再导数据" aria-label="Permalink to &quot;为什么不能直接重新建表再导数据&quot;">​</a></h2><p>重新建表再导数据容易出现字段不一致。</p><p>重新建表再导数据容易遇到外键顺序问题。</p><p>重新建表再导数据可能导致自增值、索引、约束和触发器不一致。</p><p>重新建表再导数据也容易在 DBeaver Data Transfer 中触发 <code>TRUNCATE</code> 和外键冲突。</p><p>所以这次更适合走整体迁表方案。</p><h2 id="为什么之前会遇到外键问题" tabindex="-1">为什么之前会遇到外键问题 <a class="header-anchor" href="#为什么之前会遇到外键问题" aria-label="Permalink to &quot;为什么之前会遇到外键问题&quot;">​</a></h2><p><code>TRUNCATE</code> 不只是看表里有没有数据。</p><p>只要一张表被其他表的外键引用，MySQL 就可能禁止 <code>TRUNCATE</code>。</p><p>即使目标表是空表，外键结构存在也会拦截。</p><p>所以数据库工具里的 <code>Truncate before load</code> 很容易导致失败。</p><p>这种情况下不要用右键清表或 Data Transfer 自动清表。</p><h2 id="为什么需要-root-账号" tabindex="-1">为什么需要 root 账号 <a class="header-anchor" href="#为什么需要-root-账号" aria-label="Permalink to &quot;为什么需要 root 账号&quot;">​</a></h2><p>应用账号通常只拥有旧库内部权限。</p><p>应用账号一般不能创建新库。</p><p>应用账号一般不能跨库移动表。</p><p>应用账号也不能给新数据库授权新用户。</p><p>所以数据库重命名和跨库迁移应该使用 root 或高权限账号执行。</p><h2 id="正确迁移思路" tabindex="-1">正确迁移思路 <a class="header-anchor" href="#正确迁移思路" aria-label="Permalink to &quot;正确迁移思路&quot;">​</a></h2><p>第一步是停止应用服务，避免迁移时还有新数据写入旧库。</p><p>第二步是确认旧库数据还在。</p><p>第三步是创建新数据库 <code>liuwadi</code>。</p><p>第四步是确认新数据库是空库。</p><p>第五步是删除旧库中依赖旧表名的视图和触发器。</p><p>第六步是生成 <code>RENAME TABLE</code> 迁移语句。</p><p>第七步是把 <code>liuwapocketmap.lwpm_*</code> 整体移动成 <code>liuwadi.lwd_*</code>。</p><p>第八步是检查新库中的数据量是否和旧库一致。</p><p>第九步是在新库中重建触发器。</p><p>第十步是在新库中重建视图。</p><p>第十一步是创建并授权新的应用账号 <code>liuwadi</code>。</p><p>第十二步是修改应用环境变量连接新库。</p><p>第十三步是重启应用并验证接口。</p><p>第十四步是确认线上运行正常后再考虑删除旧库。</p><h2 id="表名迁移关系" tabindex="-1">表名迁移关系 <a class="header-anchor" href="#表名迁移关系" aria-label="Permalink to &quot;表名迁移关系&quot;">​</a></h2><p><code>liuwapocketmap.lwpm_client</code> 会变成 <code>liuwadi.lwd_client</code>。</p><p><code>liuwapocketmap.lwpm_place</code> 会变成 <code>liuwadi.lwd_place</code>。</p><p><code>liuwapocketmap.lwpm_post</code> 会变成 <code>liuwadi.lwd_post</code>。</p><p><code>liuwapocketmap.lwpm_tag</code> 会变成 <code>liuwadi.lwd_tag</code>。</p><p>所有 <code>lwpm_</code> 开头的业务表都应该统一改成 <code>lwd_</code> 开头。</p><p><code>migrations</code> 表一般可以保留原名。</p><h2 id="触发器处理思路" tabindex="-1">触发器处理思路 <a class="header-anchor" href="#触发器处理思路" aria-label="Permalink to &quot;触发器处理思路&quot;">​</a></h2><p>旧触发器依赖旧表名。</p><p>迁表前应该先删除旧触发器。</p><p>迁表后应该在新库里重建新触发器。</p><p><code>trg_lwpm_place_bi_geo</code> 应该改成 <code>trg_lwd_place_bi_geo</code>。</p><p><code>trg_lwpm_place_bu_geo</code> 应该改成 <code>trg_lwd_place_bu_geo</code>。</p><p>触发器逻辑本身可以保持不变。</p><h2 id="视图处理思路" tabindex="-1">视图处理思路 <a class="header-anchor" href="#视图处理思路" aria-label="Permalink to &quot;视图处理思路&quot;">​</a></h2><p>旧视图依赖旧表名。</p><p>迁表前应该先删除旧视图。</p><p>迁表后应该在新库里重建新视图。</p><p><code>lwpm_v_public_places</code> 应该改成 <code>lwd_v_public_places</code>。</p><p><code>lwpm_v_public_posts</code> 应该改成 <code>lwd_v_public_posts</code>。</p><p>视图内部引用的表名也要全部从 <code>lwpm_</code> 改成 <code>lwd_</code>。</p><h2 id="权限处理思路" tabindex="-1">权限处理思路 <a class="header-anchor" href="#权限处理思路" aria-label="Permalink to &quot;权限处理思路&quot;">​</a></h2><p>旧账号 <code>liuwapocketmap</code> 只适合访问旧库。</p><p>新库最好创建新账号 <code>liuwadi</code>。</p><p>新账号只授权访问 <code>liuwadi.*</code>。</p><p>应用配置也应该同步改成新库名、新用户名和新密码。</p><p>这样后续维护更清晰。</p><h2 id="风险控制" tabindex="-1">风险控制 <a class="header-anchor" href="#风险控制" aria-label="Permalink to &quot;风险控制&quot;">​</a></h2><p>迁移前不要删除旧库。</p><p>迁移中不要使用 Data Transfer 反复导入。</p><p>迁移中不要手动新建一套 <code>lwd_*</code> 空表。</p><p>迁移中不要随便 <code>TRUNCATE</code> 有外键关系的表。</p><p>迁移后先验证数据量。</p><p>迁移后再验证视图。</p><p>迁移后再验证触发器。</p><p>迁移后最后验证应用功能。</p><p>旧库应该等应用稳定运行后再删除。</p><h2 id="最终结论" tabindex="-1">最终结论 <a class="header-anchor" href="#最终结论" aria-label="Permalink to &quot;最终结论&quot;">​</a></h2><p>这次数据库迁移的核心不是复制数据。</p><p>这次数据库迁移的核心是创建新库并整体移动旧表。</p><p><code>CREATE DATABASE</code> 负责准备新库。</p><p><code>RENAME TABLE</code> 负责保留数据并完成表名迁移。</p><p>重建触发器和视图负责修复旧表名依赖。</p><p>重新授权账号负责让应用连接新库。</p><p>确认应用正常后才能清理旧库。</p>',92)])])}const u=p(c,[["render",l]]);export{n as __pageData,u as default};
